/// <summary>
/// From processPending: the rows just worked, each carrying its outcome. From getQueueStatus:
/// the most recent rows regardless of status, most recently received first.
/// </summary>
[DataContractAttribute]
class HSMobileOpsPostQueueResponse
{
    boolean success;
    List    rows;

}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('Rows'),
 DataCollectionAttribute(Types::Class, classStr(HSMobileOpsPostQueueEntry))]
public List parmRows(List _value = rows)
{
    rows = _value;
    return rows;
}
